package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.EigenDecomposition;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.NonPositiveDefiniteMatrixException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.linear.SingularMatrixException;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class MultivariateNormalDistribution_sample_TriageGen0Test {

    /**
     * Test sample with a simple 1D case.
     * Verifies that the mean is returned when variance is 0 (or very small).
     */
    @Test
    public void testSample1D() {
        double[] means = {5.0};
        double[][] covariances = {{1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        double[] sample = distribution.sample();

        Assert.assertEquals(1, sample.length);
        // Since it's a distribution, we can't predict the exact value, 
        // but we check if it's a valid number.
        Assert.assertFalse(Double.isNaN(sample[0]));
    }

    /**
     * Test sample with a 2D case and a fixed seed to ensure reproducibility.
     */
    @Test
    public void testSample2DWithFixedSeed() {
        double[] means = {1.0, 2.0};
        double[][] covariances = {
            {1.0, 0.5},
            {0.5, 1.0}
        };

        // Use a fixed seed for deterministic testing
        JDKRandomGenerator rng = new JDKRandomGenerator();
        rng.setSeed(42);

        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(rng, means, covariances);

        double[] sample = distribution.sample();

        Assert.assertEquals(2, sample.length);
        // With seed 42, we expect specific values. 
        // However, for a general unit test, we verify the dimensions and non-NaN properties.
        for (double v : sample) {
            Assert.assertFalse(Double.isNaN(v));
        }
    }

    /**
     * Test sample with multiple dimensions and verify statistical properties.
     * The mean of many samples should converge to the distribution mean.
     */
    @Test
    public void testSampleStatisticalMean() {
        double[] means = {10.0, -5.0};
        double[][] covariances = {
            {1.0, 0.0},
            {0.0, 1.0}
        };
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        int numSamples = 10000;
        double sum0 = 0;
        double sum1 = 0;

        for (int i = 0; i < numSamples; i++) {
            double[] sample = distribution.sample();
            sum0 += sample[0];
            sum1 += sample[1];
        }

        double mean0 = sum0 / numSamples;
        double mean1 = sum1 / numSamples;

        // Use a tolerance for statistical convergence
        Assert.assertEquals(10.0, mean0, 0.1);
        Assert.assertEquals(-5.0, mean1, 0.1);
    }

    /**
     * Test that the sample return type and dimensions are correct.
     */
    @Test
    public void testSampleDimensions() {
        int dim = 5;
        double[] means = new double[dim];
        double[][] covariances = MatrixUtils.createRealIdentityMatrix(dim).getData();

        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);
        double[] sample = distribution.sample();

        Assert.assertNotNull(sample);
        Assert.assertEquals(dim, sample.length);
    }
}
